import * as THREE from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-card-3-label';
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const atlasW = 512;
  const atlasH = 320;
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = rect.w / rect.h;

  const planeHeight = 0.34;
  const planeWidth = planeHeight * aspect;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  const map = ctx.textureLoader('/prism-assets/chrome/ceramic-grain.map.png');
  if (map) {
    map.colorSpace = THREE.SRGBColorSpace;
    map.wrapS = THREE.ClampToEdgeWrapping;
    map.wrapT = THREE.ClampToEdgeWrapping;
  }

  const offsetX = rect.x / atlasW;
  const offsetY = 1.0 - (rect.y + rect.h) / atlasH;
  const scaleX = rect.w / atlasW;
  const scaleY = rect.h / atlasH;

  const atlasUv = uv().mul(vec2(scaleX, scaleY)).add(vec2(offsetX, offsetY));

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = texture(map, atlasUv);
  material.transparent = true;
  material.depthWrite = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'ceramic-grain-plane';
  group.add(mesh);

  const textGroup = ctx.fontAtlas.createText({
    text: 'Features 3',
    font: 'Lora',
    weight: 400,
    size: 0.14,
    color: config?.colors?.ink ?? '#16161d',
    anchor: 'center',
    maxWidth: planeWidth * 0.9,
  });
  textGroup.position.set(0, 0, 0.001);
  group.add(textGroup);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textGroup?.userData?.cleanup) {
      textGroup.userData.cleanup();
    } else if (textGroup) {
      textGroup.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    }
  };

  group.userData.billboard = (camera) => {
    group.quaternion.copy(camera.quaternion);
  };

  return group;
}
